/* Public aggregate feed generated by the source repository's push workflow. */
(()=>{
 'use strict';
 const root=new URL('.',document.currentScript.src),url=new URL('worklog/data/hackathon.json',root);
 let loading=false,lastAttempt=0;
 const $=s=>document.querySelector(s);
 const text=(tag,value,className)=>{const el=document.createElement(tag);el.textContent=value;if(className)el.className=className;return el;};
 const stamp=value=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));
 function renderDay(day){
  const box=$('#activity-feed'),data=window.portfolioActivity;if(!box||!data)return;box.replaceChildren();
  const entry=data.days.find(e=>e.date===day);
  if(!entry){box.append(text('p','이 날짜에 반영된 GitHub 기록이 없습니다.','activity-empty'));return;}
  const article=document.createElement('article');article.className='activity-entry';
  article.append(text('p','42 GLOBAL HACKATHON','activity-kicker'),text('h3',data.name),text('p',entry.summary,'activity-summary'));
  const meta=text('p',`main 브랜치 · 커밋 ${entry.commits}개 · 커밋 메시지의 작업 유형 기준`,'activity-meta');article.append(meta);
  const list=document.createElement('ul');list.className='activity-categories';for(const c of entry.categories){const li=document.createElement('li');li.append(text('span',c.label),text('strong',c.count+'건'));list.append(li);}article.append(list);
  article.append(text('p','프로젝트별 작업 요약입니다. 비공개 커밋 원문과 파일명은 공개하지 않습니다.','activity-note'));box.append(article);
 }
 window.renderGitActivity=renderDay;
 function render(data){
  window.portfolioActivity=data;
  const automatic=data.syncMode==='github-actions';
  const status=(automatic?'GitHub 자동 반영':'첫 기록 반영 · 자동 연결 설정 중')+' · '+stamp(data.syncedAt);
  if($('#activity-status'))$('#activity-status').textContent=status;
  if($('#sidebar-sync'))$('#sidebar-sync').textContent=automatic?'push → 작업 요약 → 포트폴리오':'자동 연결 설정 중';
  const latest=data.days[0],preview=$('#activity-preview');
  if(preview){preview.replaceChildren();if(latest){const a=document.createElement('a');a.href=new URL('worklog/',root).href;a.append(text('time',latest.date),text('strong',data.name),text('span',latest.summary));preview.append(a);}else preview.append(text('p','아직 반영된 기록이 없습니다.'));}
  const card=$('[data-project-id="hackathon"]');
  if(card&&latest){let badge=card.querySelector('.project-live-update');if(!badge){badge=document.createElement('a');badge.className='project-live-update';badge.href=new URL('worklog/',root).href;card.querySelector('.card-bottom').before(badge);}badge.textContent=`${latest.date} 업데이트 · ${latest.summary} ↗`;}
  document.dispatchEvent(new CustomEvent('portfolio-activity'));
 }
 function validate(data){
  if(data?.version!==1||data.projectId!=='hackathon'||!Array.isArray(data.days)||data.days.length>100||!Number.isFinite(Date.parse(data.syncedAt)))throw new Error('기록 형식을 확인할 수 없습니다.');
  for(const d of data.days){if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Number.isInteger(d.commits)||d.commits<0||typeof d.summary!=='string'||!Array.isArray(d.categories)||d.categories.some(c=>typeof c.label!=='string'||!Number.isInteger(c.count)||c.count<0))throw new Error('기록 형식을 확인할 수 없습니다.');}
  return data;
 }
 async function refresh(){
  if(loading||Date.now()-lastAttempt<10000)return;loading=true;lastAttempt=Date.now();if($('#activity-refresh'))$('#activity-refresh').disabled=true;
  try{const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw new Error('기록을 불러오지 못했습니다.');render(validate(await r.json()));}
  catch(e){if($('#activity-status'))$('#activity-status').textContent=window.portfolioActivity?'갱신 연결 실패 · 마지막으로 받은 기록을 표시합니다.':'GitHub 기록을 불러오지 못했습니다.';if(!window.portfolioActivity&&$('#activity-feed'))$('#activity-feed').textContent='연결을 확인하고 업데이트 확인을 눌러주세요.';}
  finally{loading=false;if($('#activity-refresh'))$('#activity-refresh').disabled=false;}
 }
 $('#activity-refresh')?.addEventListener('click',refresh);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
 setInterval(()=>{if(!document.hidden)refresh();},60000);refresh();
})();
